CREATE OR REPLACE FUNCTION public.admin_dashboard_metrics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN jsonb_build_object('clicks7',(SELECT count(*) FROM public.outbound_clicks WHERE created_at>=now()-interval '7 days'),'clicks30',(SELECT count(*) FROM public.outbound_clicks WHERE created_at>=now()-interval '30 days'),'subscribers',(SELECT count(*) FROM public.price_alert_subscribers),'daily',(SELECT coalesce(jsonb_agg(t),'[]') FROM (SELECT to_char(d.day,'DD/MM') AS label,count(c.id) AS count FROM generate_series(date_trunc('day',now() AT TIME ZONE 'America/Sao_Paulo')-interval '29 days',date_trunc('day',now() AT TIME ZONE 'America/Sao_Paulo'),interval '1 day') d(day) LEFT JOIN public.outbound_clicks c ON (c.created_at AT TIME ZONE 'America/Sao_Paulo')::date=d.day::date GROUP BY d.day ORDER BY d.day) t)); END $$;
REVOKE ALL ON FUNCTION public.admin_dashboard_metrics() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_dashboard_metrics() TO authenticated,service_role;